import json,hashlib,pathlib
out=[]
def flat(o,p=''):
  if isinstance(o,dict):
    for k,v in o.items(): yield from flat(v,p+'.'+k)
  elif isinstance(o,list):
    for i,v in enumerate(o): yield from flat(v,p+'[%d]'%i)
  else: yield p,o
skip=('contactPoint','email','telephone','faxNumber','.address','identifier')
for n in ['105806-2026','105970-2026','105743-2026']:
  f='products/services/software-awards/raw/ocds-%s.json'%n
  b=open(f,'rb').read(); d=json.loads(b)
  out.append('===== %s sha256 %s bytes %d'%(n,hashlib.sha256(b).hexdigest(),len(b)))
  for p,v in flat(d):
    if any(s in p for s in skip): continue
    s=str(v)
    if len(s)>700: s=s[:700]+'...'
    out.append('%s = %s'%(p,s))
pathlib.Path('products/services/software-awards/raw/flat.txt').write_text('\n'.join(out))
print(len(out))
